arguments.command:
curl -sS -m 30 -X POST https://api.linear.app/graphql -H 'Content-Type: application/json' -H "Authorization: <TOKEN>" -d '{"query":"{ q: __type(name: \"Query\") { fields(includeDeprecated: true) { name args { name type { name kind ofType { name } } } } } }"}' > /tmp/q.json
python3 - <<'EOF'
import json
d = json.load(open('/tmp/q.json'))
fields = {x['name']: x['args'] for x in d['data']['q']['fields']}
for k in ['attachments','searchIssues','attachment','issueSearch','semanticSearch']:
    if k in fields:
        print(k, '->', json.dumps(fields[k]))
EOF

